import{_ as n,o as a,c as t,a5 as s}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"82. Portability and Endianness","description":"The Little Book of C — 82. Portability and Endianness","frontmatter":{"title":"82. Portability and Endianness","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Portable and Modern C"],"description":"The Little Book of C — 82. Portability and Endianness","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":82,"sidebarWeight":82,"lang":"en-US","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/082-Portability and Endianness","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/082-Portability and Endianness"},"headers":[],"relativePath":"posts/c教程/en-US/09-Portable and Modern C/082-Portability and Endianness.md","filePath":"posts/c教程/en-US/09-Portable and Modern C/082-Portability and Endianness.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/09-Portable and Modern C/082-Portability and Endianness.md"};function o(l,e,d,p,r,c){return a(),t("div",null,[...e[0]||(e[0]=[s(`<p>[中文版本](/posts/c教程/zh-CN/09-可移植与现代 C/082-Portability and Endianness)</p><p>Portability means your C program behaves the same way everywhere, on Linux, Windows, ARM, x86, or even a tiny microcontroller. Writing portable code is one of the hardest and most important skills in systems programming.</p><p>This section helps you understand the biggest low-level trap of all: endianness, and how to write code that runs safely across architectures.</p><h4 id="step-1-what-is-portability" tabindex="-1">Step 1. What Is Portability? <a class="header-anchor" href="#step-1-what-is-portability" aria-label="Permalink to &quot;Step 1. What Is Portability?&quot;">​</a></h4><p>A portable C program is one that:</p><ul><li>Compiles cleanly with different compilers.</li><li>Runs correctly on 32-bit, 64-bit, and embedded systems.</li><li>Does not assume details of CPU, OS, or compiler behavior.</li></ul><p>Portability depends on respecting what the C standard guarantees, and avoiding assumptions that might be true only on your machine.</p><h4 id="step-2-why-portability-matters" tabindex="-1">Step 2. Why Portability Matters <a class="header-anchor" href="#step-2-why-portability-matters" aria-label="Permalink to &quot;Step 2. Why Portability Matters&quot;">​</a></h4><p>You might write a C program on macOS (little-endian x86_64) and later need to run it on:</p><ul><li>A Raspberry Pi (ARM, also little-endian)</li><li>A big-endian PowerPC router</li><li>An embedded MIPS controller</li></ul><p>If your program reads or writes binary data, it must handle endianness, or the same file may be misread on another architecture.</p><h4 id="step-3-understanding-endianness" tabindex="-1">Step 3. Understanding Endianness <a class="header-anchor" href="#step-3-understanding-endianness" aria-label="Permalink to &quot;Step 3. Understanding Endianness&quot;">​</a></h4><p>Endianness defines how bytes of multibyte values are stored in memory.</p><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>Memory (4-byte int = 0x12345678)</th></tr></thead><tbody><tr><td>Little-endian</td><td>Least significant byte first</td><td><code>78 56 34 12</code></td></tr><tr><td>Big-endian</td><td>Most significant byte first</td><td><code>12 34 56 78</code></td></tr></tbody></table><p>Intel and ARM (in most modes) are little-endian. Many older CPUs (PowerPC, SPARC) are big-endian.</p><p>C does not define the byte order, it depends on the platform.</p><h4 id="step-4-checking-endianness-at-runtime" tabindex="-1">Step 4. Checking Endianness at Runtime <a class="header-anchor" href="#step-4-checking-endianness-at-runtime" aria-label="Permalink to &quot;Step 4. Checking Endianness at Runtime&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    unsigned int x = 0x12345678;</span></span>
<span class="line"><span>    unsigned char *p = (unsigned char *)&amp;x;</span></span>
<span class="line"><span>    if (*p == 0x78)</span></span>
<span class="line"><span>        printf(&quot;Little-endian\\n&quot;);</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        printf(&quot;Big-endian\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Explanation: The pointer<code>p</code> reads the lowest memory byte. If it contains the least significant byte (<code>0x78</code>), it’s little-endian.</p><h4 id="step-5-converting-between-endiannesses" tabindex="-1">Step 5. Converting Between Endiannesses <a class="header-anchor" href="#step-5-converting-between-endiannesses" aria-label="Permalink to &quot;Step 5. Converting Between Endiannesses&quot;">​</a></h4><p>Use standard POSIX functions to handle conversions safely:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;arpa/inet.h&gt;</span><span>  // or &lt;winsock2.h&gt; on Windows</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    uint32_t x = 0x12345678;</span></span>
<span class="line"><span>    uint32_t y = htonl(x); // Host to Network Long (big-endian)</span></span>
<span class="line"><span>    printf(&quot;0x%x -&gt; 0x%x\\n&quot;, x, y);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Functions:</p><ul><li><code>htons</code>– host to network short (16-bit)</li><li><code>htonl</code>– host to network long (32-bit)</li><li><code>ntohs</code>– network to host short</li><li><code>ntohl</code>– network to host long</li></ul><p>Network byte order is always big-endian.</p><h4 id="step-6-handling-portability-in-file-formats" tabindex="-1">Step 6. Handling Portability in File Formats <a class="header-anchor" href="#step-6-handling-portability-in-file-formats" aria-label="Permalink to &quot;Step 6. Handling Portability in File Formats&quot;">​</a></h4><p>If you serialize structs directly to disk:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fwrite(&amp;header, sizeof(header), 1, file);</span></span></code></pre></div><p>you’re likely writing machine-dependent data:</p><ul><li>Endianness may differ.</li><li>Padding and alignment may differ.</li><li>Structure layout can vary by compiler.</li></ul><p>Better approach: Write each field individually in a well-defined order:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t size_net = htonl(header.size);</span></span>
<span class="line"><span>fwrite(&amp;size_net, sizeof(size_net), 1, file);</span></span></code></pre></div><p>Now, any machine can read your file by reversing the conversion (<code>ntohl</code>).</p><h4 id="step-7-data-type-size-differences" tabindex="-1">Step 7. Data Type Size Differences <a class="header-anchor" href="#step-7-data-type-size-differences" aria-label="Permalink to &quot;Step 7. Data Type Size Differences&quot;">​</a></h4><p>Type sizes vary across systems:</p><table tabindex="0"><thead><tr><th>Type</th><th>Typical 32-bit</th><th>Typical 64-bit</th></tr></thead><tbody><tr><td><code>char</code></td><td>1 byte</td><td>1 byte</td></tr><tr><td><code>short</code></td><td>2 bytes</td><td>2 bytes</td></tr><tr><td><code>int</code></td><td>4 bytes</td><td>4 bytes</td></tr><tr><td><code>long</code></td><td>4 bytes</td><td>8 bytes</td></tr><tr><td><code>long long</code></td><td>8 bytes</td><td>8 bytes</td></tr><tr><td><code>void*</code></td><td>4 bytes</td><td>8 bytes</td></tr></tbody></table><p>Use<code>&lt;stdint.h&gt;</code> types (<code>int32_t</code>,<code>uint64_t</code>, etc.) for predictable sizes.</p><h4 id="step-8-alignment-and-padding" tabindex="-1">Step 8. Alignment and Padding <a class="header-anchor" href="#step-8-alignment-and-padding" aria-label="Permalink to &quot;Step 8. Alignment and Padding&quot;">​</a></h4><p>The compiler may insert padding between structure fields for speed or alignment.</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct Example {</span></span>
<span class="line"><span>    char a;</span></span>
<span class="line"><span>    int b;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>On most systems:</p><ul><li><code>sizeof(struct Example)</code>= 8, not 5 (3 bytes of padding).</li></ul><p>To make portable formats:</p><ul><li>Use<code>#pragma pack(1)</code>(non-standard) or serialize field-by-field.</li><li>Never assume<code>sizeof(struct)</code> is the same across systems.</li></ul><h4 id="step-9-compiler-and-os-differences" tabindex="-1">Step 9. Compiler and OS Differences <a class="header-anchor" href="#step-9-compiler-and-os-differences" aria-label="Permalink to &quot;Step 9. Compiler and OS Differences&quot;">​</a></h4><p>Be careful with:</p><ul><li>Path separators (<code>/</code> vs<code>\\\\</code>)</li><li>Newline conventions (<code>\\n</code> vs<code>\\r\\n</code>)</li><li><code>#include &lt;unistd.h&gt;</code>(POSIX only)</li><li><code>system()</code> commands (OS-specific)</li><li>Thread APIs (<code>pthread</code> vs Windows threads)</li><li>Socket APIs (<code></code> vs<code>&lt;winsock2.h&gt;</code>)</li></ul><p>Use conditional compilation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef _WIN32</span></span>
<span class="line"><span>#include &lt;winsock2.h&gt;</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>#include &lt;arpa/inet.h&gt;</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="step-10-tiny-code-writing-portable-binary-i-o" tabindex="-1">Step 10. Tiny Code: Writing Portable Binary I/O <a class="header-anchor" href="#step-10-tiny-code-writing-portable-binary-i-o" aria-label="Permalink to &quot;Step 10. Tiny Code: Writing Portable Binary I/O&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;arpa/inet.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;num.bin&quot;, &quot;wb&quot;);</span></span>
<span class="line"><span>    uint32_t n = 0x12345678;</span></span>
<span class="line"><span>    uint32_t net = htonl(n);</span></span>
<span class="line"><span>    fwrite(&amp;net, sizeof(net), 1, f);</span></span>
<span class="line"><span>    fclose(f);</span></span>
<span class="line"><span>    f = fopen(&quot;num.bin&quot;, &quot;rb&quot;);</span></span>
<span class="line"><span>    uint32_t read_net;</span></span>
<span class="line"><span>    fread(&amp;read_net, sizeof(read_net), 1, f);</span></span>
<span class="line"><span>    fclose(f);</span></span>
<span class="line"><span>    printf(&quot;Read back: 0x%x\\n&quot;, ntohl(read_net));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This program writes and reads a 32-bit integer in portable big-endian form, the same bytes on any machine.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Portability ensures your software lives longer than your hardware. A portable program:</p><ul><li>Runs on different CPUs and OSes.</li><li>Shares data safely across architectures.</li><li>Builds trust in your code across teams and systems.</li></ul><p>Portability is a kind of professionalism, future-proofing your code.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a program that detects and prints system endianness.</li><li>Serialize a struct to a binary file, then deserialize it on another system.</li><li>Use<code>htonl</code> and<code>ntohl</code> to ensure data stays consistent.</li><li>Compile your code with both GCC and Clang.</li><li>Test it on both 32-bit and 64-bit architectures.</li></ol><p>Next, you’ll explore inline assembly and hardware access, the bridge between pure C and the underlying CPU instructions.</p>`,60)])])}const b=n(i,[["render",o]]);export{u as __pageData,b as default};
